Every limiter (and the FastAPI app) obtains time through a ``Clock`` so that
tests can drive deterministic, simulated schedules.
"""
from __future__ import annotations

import time
from typing import Protocol, runtime_checkable


@runtime_checkable
class Clock(Protocol):
    def now(self) -> float:
        """Return the current simulated or real time in seconds."""
        ...


class SystemClock:
    """Wall-clock backed by ``time.monotonic``."""

    def now(self) -> float:
        return time.monotonic()


class ManualClock:
    """Deterministic clock for tests: advance or jump it by hand."""

    def __init__(self, start: float = 0.0) -> None:
        self._now = float(start)

    def now(self) -> float:
        return self._now

    def advance(self, seconds: float) -> float:
        self._now += float(seconds)
        return self._now

    def set(self, value: float) -> float:
        self._now = float(value)
        return self._now
