Keeps the timestamps of admitted requests per key. A request is admitted iff
fewer than ``limit`` admitted timestamps fall in the open-closed interval
``(now - period, now]``. This is exact: no rolling 60s window ever contains
more than ``limit`` admissions.
"""
from __future__ import annotations

from collections import deque
from dataclasses import dataclass

from .base import Decision, RateLimiter


@dataclass
class _KeyState:
    log: deque  # sorted admitted timestamps within the trailing window


class SlidingLogLimiter(RateLimiter):
    def _initial_state(self) -> _KeyState:
        return _KeyState(log=deque())

    def _prune(self, state: _KeyState, now: float) -> None:
        cutoff = now - self.period
        log = state.log
        while log and log[0] <= cutoff:
            log.popleft()

    def _check(self, state: _KeyState, now: float) -> Decision:
        self._prune(state, now)
        log = state.log
        if len(log) < self.limit:
            log.append(now)
            return Decision(
                allowed=True,
                retry_after=0.0,
                limit=self.limit,
                remaining=self.limit - len(log),
            )
        # The oldest entry will leave the window at oldest + period,
        # freeing exactly one slot.
        retry_after = max(0.0, log[0] + self.period - now)
        return Decision(
            allowed=False,
            retry_after=retry_after,
            limit=self.limit,
            remaining=0,
        )

    def oldest_exit(self, key: str, now: float) -> float:
        """When the currently-oldest logged admission exits the window."""
        state = self._states.get(key)
        if state is None or not state.log:
            return now
        self._prune(state, now)
        return state.log[0] + self.period
"})
