from hypothesis import given, settings
from hypothesis import strategies as st

from ratelimit.fixed_window import FixedWindowLimiter

from conftest import LIMIT, PERIOD, run_schedule


def make():
    return FixedWindowLimiter(limit=LIMIT, period=PERIOD)


# ---- invariant: never more than LIMIT admissions in any aligned minute ----
@given(schedule=st.lists(st.integers(min_value=0, max_value=300), max_size=400))
@settings(max_examples=200, deadline=None)
def test_never_exceeds_limit_per_aligned_minute(schedule):
    limiter = make()
    decisions = run_schedule(limiter, sorted(schedule))
    for minute in range(6):
        lo, hi = minute * 60, (minute + 1) * 60 - 1
        admitted = sum(
            1 for t, d in zip(sorted(schedule), decisions) if lo <= t <= hi and d.allowed
        )
        assert admitted <= LIMIT


@given(schedule=st.lists(st.integers(min_value=0, max_value=300), max_size=400))
@settings(max_examples=100, deadline=None)
def test_decision_shape(schedule):
    for d in run_schedule(make(), sorted(schedule)):
        if d.allowed:
            assert d.retry_after == 0.0
        else:
            assert 0.0 < d.retry_after <= PERIOD
        assert d.limit == LIMIT


def test_thirtieth_admitted_thirty_first_denied():
    limiter = make()
    decisions = [limiter.check("k", float(t)) for t in range(30)]
    assert all(d.allowed for d in decisions)
    denied = limiter.check("k", 29.0)
    assert not denied.allowed
    # window [0,60) ends at t=60 -> retry after 31s from t=29
    assert denied.retry_after == pytest_approx(31.0)


def pytest_approx(value):
    return pytest_float(value)


def pytest_float(v):
    import pytest as _p
    return _p.approx(v)


def test_counter_resets_on_new_window():
    limiter = make()
    for t in range(30):
        assert limiter.check("k", float(t)).allowed
    assert not limiter.check("k", 59.9).allowed
    assert limiter.check("k", 60.0).allowed  # fresh aligned window
    for i in range(29):
        assert limiter.check("k", 60.0).allowed
    assert not limiter.check("k", 60.0).allowed


def test_keys_are_independent():
    limiter = make()
    for t in range(30):
        limiter.check("a", float(t))
    assert not limiter.check("a", 10.0).allowed
    assert limiter.check("b", 10.0).allowed


def test_retry_after_math_exact():
    limiter = make()
    for _ in range(30):
        limiter.check("k", 5.0)
    d = limiter.check("k", 45.0)
    assert d.retry_after == 15.0  # next aligned window starts at 60
    d = limiter.check("k", 59.5)
    assert d.retry_after == 0.5
