from hypothesis import given, settings
from hypothesis import strategies as st

from ratelimit.sliding_log import SlidingLogLimiter

from conftest import LIMIT, PERIOD, run_schedule


def make():
    return SlidingLogLimiter(limit=LIMIT, period=PERIOD)


# ---- invariant: any rolling 60s window (t-60, t] holds at most LIMIT admissions ----
@given(schedule=st.lists(st.integers(min_value=0, max_value=300), max_size=400))
@settings(max_examples=200, deadline=None)
def test_never_exceeds_limit_in_any_rolling_window(schedule):
    ordered = sorted(schedule)
    decisions = run_schedule(make(), ordered)
    admitted_times = sorted(t for t, d in zip(ordered, decisions) if d.allowed)
    # The maximum of a rolling-window count is attained with its right edge
    # on some admitted timestamp.
    for i, t in enumerate(admitted_times):
        in_window = [s for s in admitted_times[: i + 1] if t - 60 < s <= t]
        assert len(in_window) <= LIMIT


def test_burst_at_single_instant_capped():
    limiter = make()
    decisions = [limiter.check("k", 100.0) for _ in range(35)]
    assert sum(d.allowed for d in decisions) == LIMIT


def test_entries_expire_immediately_at_boundary():
    limiter = make()
    for _ in range(LIMIT):
        assert limiter.check("k", 0.0).allowed
    assert not limiter.check("k", 59.0).allowed   # still inside (0-60, 59]
    assert not limiter.check("k", 59.999).allowed
    assert limiter.check("k", 60.0).allowed       # t=0 entries left the window
    assert limiter.check("k", 120.5).allowed      # long idle, fresh again


def test_keys_are_independent():
    limiter = make()
    for _ in range(LIMIT):
        limiter.check("a", 1.0)
    assert not limiter.check("a", 2.0).allowed
    assert limiter.check("b", 2.0).allowed


@given(schedule=st.lists(st.integers(min_value=0, max_value=300), max_size=400))
@settings(max_examples=100, deadline=None)
def test_denied_implies_full_window(schedule):
    """A denial must imply LIMIT admissions inside (now-60, now]."""
    limiter = make()
    for t in sorted(schedule):
        d = limiter.check("k", float(t))
        if not d.allowed:
            live = [s for s in limiter._states["k"].log if t - 60 < s <= t]
            assert len(live) == LIMIT
"})
