result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ratelimit-service/tests/test_differential.py", "content": """"HTTP-level tests for POST /check with an injected ManualClock."""
import pytest
from fastapi.testclient import TestClient

from ratelimit.app import create_app
from ratelimit.clock import ManualClock

from conftest import LIMIT, PERIOD


@pytest.fixture
def clock():
    return ManualClock(start=100.0)


@pytest.fixture
def client(clock):
    app = create_app(clock)
    return TestClient(app)


def _check(client, algorithm="fixed_window", key="k"):
    return client.post("/check", json={"key": key, "algorithm": algorithm})


def test_admits_30_then_429_with_retry_after_header(client):
    statuses = [_check(client).status_code for _ in range(35)]
    assert statuses[:LIMIT] == [200] * LIMIT
    assert statuses[LIMIT:] == [429] * 5

    r = _check(client)
    assert r.json()["allowed"] is False
    assert int(r.headers["Retry-After"]) == 60  # next minute at t=160
    body = r.json()
    assert body["retry_after"] == pytest.approx(60.0)
    assert body["limit"] == LIMIT


def test_counter_resets_when_clock_advances(client, clock):
    for _ in range(LIMIT):
        assert _check(client).status_code == 200
    assert _check(client).status_code == 429
    clock.advance(PERIOD)
    assert _check(client).status_code == 200


def test_algorithms_share_the_clock_but_not_state(clock):
    client = TestClient(create_app(clock))
    for name in ("fixed_window", "sliding_log", "token_bucket"):
        codes = [_check(client, algorithm=name).status_code for _ in range(LIMIT + 1)]
        assert codes[:LIMIT] == [200] * LIMIT
        assert codes[-1] == 429


def test_keys_are_isolated(client):
    for _ in range(LIMIT):
        _check(client, key="alice")
    assert _check(client, key="alice").status_code == 429
    assert _check(client, key="bob").status_code == 200


def test_unknown_algorithm_rejected(client):
    r = client.post("/check", json={"key": "k", "algorithm": "leaky_bucket"})
    assert r.status_code == 422


def test_validation_errors(client):
    assert client.post("/check", json={"algorithm": "fixed_window"}).status_code == 422
    assert client.post("/check", json={"key": "", "algorithm": "fixed_window"}).status_code == 422


def test_token_bucket_retry_after_header_math(clock):
    client = TestClient(create_app(clock))
    for _ in range(LIMIT):
        _check(client, algorithm="token_bucket")
    clock.advance(1.0)  # half a token accrued (rate 0.5/s) -> 1s more needed
    r = _check(client, algorithm="token_bucket")
    assert r.status_code == 429
    assert int(r.headers["Retry-After"]) == 1
    assert r.json()["retry_after"] == pytest.approx(1.0)


def test_default_app_uses_system_clock():
    from ratelimit.app import app as default_app

    client = TestClient(default_app)
    assert isinstance(default_app.state.clock.__class__.__name__, str)
    r = _check(client)
    assert r.status_code == 200
